      kept ||= c.settledDue != null || (isBound(c) && c.statedDue != null)
        || (due != null && (grade !== p.grade || (todayDate !== undefined && c.date <= todayDate)));
      sum += due ?? 0n;
    }
    totals.set(p.id, today.has(p.grade) || kept ? sum : null);
  }
  return totals;
